from typing import Optional, Union

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class CreateChatResultsSchema(pydantic.BaseModel):
    sn: str


class CreateChatResponseSchema(BaseRapiResponseSchema):
    results: CreateChatResultsSchema


class JoinChatResponseSchema(BaseRapiResponseSchema): ...


class ModChatResponseSchema(BaseRapiResponseSchema): ...


class ModChatMemberResponseSchema(BaseRapiResponseSchema): ...


class You(pydantic.BaseModel):
    role: Optional[str] = None
    inviter: Optional[str] = None


class UserState(pydantic.BaseModel):
    lastseen: int


class Anketa(pydantic.BaseModel):
    sn: str
    firstName: str
    lastName: str
    nick: Optional[str]
    friendly: str
    abName: Optional[str] = None
    honours: Optional[list[str]] = None


class Member(pydantic.BaseModel):
    sn: str
    role: str
    friendly: str
    userState: UserState
    anketa: Anketa
    noAvatar: Optional[str] = None


class Person(pydantic.BaseModel):
    sn: Union[int, str]
    firstName: str
    lastName: str
    nick: Optional[str]
    friendly: str


class GetChatInfoResultsSchema(pydantic.BaseModel):
    you: You
    members: list[Member]
    persons: list[Person]
    threadsAutoSubscribe: bool
    threadsAutoSubscribeWithExisting: bool
    sn: str
    stamp: str
    name: str
    about: Optional[str]
    rules: Optional[str]
    createTime: int
    creator: str
    defaultRole: str
    regions: str
    public: Optional[bool]
    live: bool
    controlled: bool
    approved: Optional[bool]
    joinModeration: Optional[bool]
    lookingEnabled: Optional[bool]
    trustRequired: Optional[bool]
    threadsEnabled: bool
    adminsCount: int
    membersCount: int
    blockedCount: Optional[int]
    pendingCount: Optional[int]
    invitationsCount: Optional[int]
    membersVersion: int
    infoVersion: int
    avatarLastModified: Optional[int]
    abuseReportsCurrentCount: int


class GetChatInfoResponseSchema(BaseRapiResponseSchema):
    results: GetChatInfoResultsSchema


class GetChatMembersResponseSchema(BaseRapiResponseSchema):
    results: dict[str, dict]


class SearchChatMembersResponseSchema(BaseRapiResponseSchema):
    results: dict[str, dict]


class GroupSubscribeResponseSchema(BaseRapiResponseSchema): ...


class GroupMembersAddResponseSchema(BaseRapiResponseSchema): ...


class GroupMembersDeleteResponseSchema(BaseRapiResponseSchema): ...


class CheckGroupStampResponseSchema(BaseRapiResponseSchema): ...


class SuggestGroupStampResultsSchema(pydantic.BaseModel):
    stamp: str


class SuggestPublicGroupStampResponseSchema(BaseRapiResponseSchema):
    results: SuggestGroupStampResultsSchema


class SuggestPrivateGroupStampResponseSchema(BaseRapiResponseSchema):
    results: SuggestGroupStampResultsSchema


class GroupPendingAcceptResponseSchema(BaseRapiResponseSchema): ...


class GroupPendingRejectResponseSchema(BaseRapiResponseSchema): ...


class GroupPendingCancelResponseSchema(BaseRapiResponseSchema): ...


class GroupInvitationsCancelResponseSchema(BaseRapiResponseSchema): ...


class BlockChatMemberResponseSchema(BaseRapiResponseSchema): ...


class UnblockChatMemberResponseSchema(BaseRapiResponseSchema): ...


class Item(pydantic.BaseModel):
    sn: str
    firstName: Optional[str] = None
    lastName: Optional[str] = None
    nick: Optional[str] = None
    about: str
    bot: Optional[bool] = None
    avatarId: Optional[str] = None
    friendly: Optional[str] = None
    name: Optional[str] = None
    stamp: Optional[str] = None
    createTime: Optional[int] = None
    creator: Optional[str] = None
    public: Optional[bool] = None
    live: Optional[bool] = None
    controlled: Optional[bool] = None
    infoVersion: Optional[str] = None
    membersVersion: Optional[str] = None
    membersCount: Optional[int] = None
    adminsCount: Optional[int] = None
    defaultRole: Optional[str] = None
    lookingEnabled: Optional[bool] = None
    regions: Optional[str] = None
    expoType: Optional[str] = None
    ticket: Optional[str] = None
    you: Optional[You] = None


class GetChatHomeResultsSchema(pydantic.BaseModel):
    items: list[Item]
    persons: list[Person]


class GetChatHomeResponseSchema(BaseRapiResponseSchema):
    results: GetChatHomeResultsSchema


class Chat(pydantic.BaseModel):
    membersCount: int
    name: str
    sn: str


class GetCommonChatsResultsSchema(pydantic.BaseModel):
    chats: list[Chat]
    persons: list[Person]


class GetCommonChatsResponseSchema(BaseRapiResponseSchema):
    results: GetCommonChatsResultsSchema


class DelHistoryResponseSchema(BaseRapiResponseSchema): ...
